{
  "name": "docs-server",
  "version": "0.2.1",
  "capabilities": {
    "tools":     { "listChanged": true },
    "resources": { "subscribe":   true, "listChanged": true }
  },
  "tools": [
    {
      "name": "search_docs",
      "description": "Searches for relevant passages in the documentation base.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query":   { "type": "string" },
          "top_k":   { "type": "integer", "default": 5 }
        },
        "required": ["query"]
      }
    }
  ],
  "resources": [
    {
      "uri":  "file:///docs/architecture.md",
      "name": "architecture",
      "mimeType": "text/markdown"
    }
  ]
}

