import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';

const transport = new StdioClientTransport({
  command: 'npx', args: ['-y', '@modelcontextprotocol/server-filesystem', '/docs'],
});

const client = new Client({ name: 'host', version: '1.0.0' }, { capabilities: {} });
await client.connect(transport);

const { tools }     = await client.listTools();     // -> catalog for the LLM
const { resources } = await client.listResources(); // -> available data

const result = await client.callTool({
  name: 'search_docs',
  arguments: { query: 'how does checkpoint work', top_k: 3 },
});
